import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());

  // If `selected` matches no tab, the first tab is the active one.
  const activeTab = tabs.find((tab) => tab.id === selected) ?? tabs[0];

  const moveTo = (index: number) => {
    const tab = tabs[index];
    if (!tab) return;
    onSelect(tab.id);
    buttonRefs.current.get(tab.id)?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const last = tabs.length - 1;
    let next: number;

    switch (event.key) {
      case "ArrowRight":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    moveTo(next);
  };

  const panelId = `${baseId}-panel`;

  return (
    <div className="tab-strip">
      <div role="tablist" className="tab-strip__list">
        {tabs.map((tab, index) => {
          const isSelected = tab.id === activeTab?.id;
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              id={`${baseId}-tab-${tab.id}`}
              aria-selected={isSelected}
              aria-controls={panelId}
              tabIndex={isSelected ? 0 : -1}
              className="tab-strip__tab"
              ref={(element) => {
                if (element) {
                  buttonRefs.current.set(tab.id, element);
                } else {
                  buttonRefs.current.delete(tab.id);
                }
              }}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={panelId}
        aria-labelledby={activeTab ? `${baseId}-tab-${activeTab.id}` : undefined}
        tabIndex={0}
        className="tab-strip__panel"
      >
        {children}
      </div>
    </div>
  );
}
```

