```css
.tab-strip {
  display: flex;
  flex-direction: column;
  color: var(--ink);
  font: inherit;
}

.tab-strip__list {
  display: flex;
  gap: clamp(0.25rem, 0.5vw, 0.5rem);
  border-bottom: 1px solid var(--hair);
  margin-bottom: -1px;
  overflow-x: auto;
}

.tab-strip__tab {
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1.05rem);
  color: var(--muted);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  padding: 0.6em 0.9em;
  cursor: pointer;
  white-space: nowrap;
  transition: color 150ms ease, border-color 150ms ease;
}

.tab-strip__tab:hover {
  color: var(--ink);
}

.tab-strip__tab[aria-selected="true"] {
  color: var(--ink);
  border-bottom-color: var(--myelin);
}

.tab-strip__panel {
  padding: clamp(1rem, 2vw, 1.5rem) 0;
  color: var(--ink);
  font: inherit;
}

:root[data-motion="reduce"] .tab-strip__tab {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab {
    transition: none;
  }
}
```

